function openMemory(){const game=++memoryGame;let cards=['⌘','✧','◈','⌬','☀','◉'];cards=[...cards,...cards];for(let i=cards.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[cards[i],cards[j]]=[cards[j],cards[i]]}let first=null,locked=false,matches=0,moves=0;showPanel('DESAFIO · ILHA DO PLAY',`<h2>Memória criativa.</h2><p class="lead">Encontre os seis pares. Complete o desafio para conquistar um selo e 200 XP.</p><div class="memoryboard">${cards.map((c,i)=>`<button data-card="${i}" aria-label="Revelar carta ${i+1}">?</button>`).join('')}</div><p id="memoryStatus" class="lead">0 pares · 0 tentativas</p><button class="secondary" id="returnDiary">Voltar ao diário</button>`);$('#returnDiary').onclick=openQuests;$$('[data-card]').forEach(b=>b.onclick=()=>{if(locked||b.classList.contains('flipped')||b.classList.contains('matched'))return;b.textContent=cards[+b.dataset.card];b.classList.add('flipped');b.setAttribute('aria-label',b.textContent);tone(420);if(!first){first=b;return}moves++;const a=first;first=null;if(a.textContent===b.textContent){a.classList.add('matched');b.classList.add('matched');matches++;if(matches===6){if(!progress.memory){progress.memory=true;updateProgress();toast('Selo Memória criativa conquistado · +200 XP')}tone(880,.3)}}else{locked=true;setTimeout(()=>{if(game!==memoryGame)return;[a,b].forEach(x=>{x.classList.remove('flipped');x.textContent='?';x.setAttribute('aria-label','Revelar carta '+(+x.dataset.card+1))});locked=false},800)}$('#memoryStatus').textContent=matches===6?'Desafio concluído! '+moves+' tentativas.':matches+' pares · '+moves+' tentativas'})}
